"""Observed reply values and bounded continuation estimates; never an execution policy.

All currency comparisons use the same supplier-economic scenarios on both sides.
Reply probabilities and counter scenarios are estimates, not calibrated facts.
"""

import math
from collections import Counter

from arena_kit.cost import closing_terms, must_haves_ok

OUTCOMES = ('accepted_proposal', 'improved_counteroffer', 'unchanged_offer', 'worse_offer', 'walkout')
COUNTERS = OUTCOMES[1:4]


def paired_gain(th, before, after):
    old, new = th.economics.breakdowns(before), th.economics.breakdowns(after)
    values = [sum(a.values()) - sum(b.values()) for a, b in zip(old, new, strict=True)]
    return {'mean': sum(values) / len(values), 'low': min(values), 'high': max(values)}


def features(th, terms, before, status, repeats):
    old = closing_terms(th.beliefs.case, before, th.std)
    new = closing_terms(th.beliefs.case, terms, th.std)
    pressure = th.beliefs.pressure_summary(new, old)
    levers = {k: new[k] for k in th.beliefs.case['negotiable'] if k != 'unit_price' and new[k] != old[k]}
    return {'pressure': pressure['mean'], 'pressure_range': [pressure['low'], pressure['high']],
            'price_request_fraction': (old['unit_price'] - new['unit_price']) / max(0.01, old['unit_price']),
            'levers': levers, 'status': status, 'repeats': repeats,
            'opening': before == th.reference or all(before.get(k) == v for k, v in th.reference.items()
                                                    if k in before)}


def comparable(th, x):
    rows = []
    for row in getattr(th, 'response_history', []):
        y = row['features']
        if y['status'] == 'final_offer' or x['status'] == 'final_offer':
            if y['status'] != x['status']:
                continue
        # Unmatched multi-package choices cannot identify the supplier's trade-off.
        if not row['identified_offer']:
            continue
        mismatches = sum(x['levers'].get(k) != y['levers'].get(k) for k in set(x['levers']) | set(y['levers']))
        distance = 8 * abs(x['pressure'] - y['pressure']) + mismatches * 1.5
        distance += 0.7 * (x['opening'] != y['opening']) + 0.3 * abs(x['repeats'] - y['repeats'])
        rows.append((math.exp(-distance), row))
    rows.sort(key=lambda pair: pair[0], reverse=True)
    rows = rows[:12]
    counts = Counter(row['session_id'] for _, row in rows)
    return [(weight / counts[row['session_id']], row) for weight, row in rows]


def reply_probabilities(th, terms, before, status, repeats, neighbors=None):
    b = th.beliefs
    base = {k: sum(p.weight * b.probabilities(terms, p, before['unit_price'], repeats,
                                             standing=before)[k] for p in b.particles)
            for k in ('accept', 'counter', 'walk')}
    neighbors = comparable(th, features(th, terms, before, status, repeats)) if neighbors is None else neighbors
    # Equal one-observation pseudo-counts express ignorance about counter quality.
    counts = {k: 1.0 for k in COUNTERS}
    for weight, row in neighbors:
        if row['economic_label'] in counts:
            counts[row['economic_label']] += weight
    total = sum(counts.values())
    return {'accepted_proposal': base['accept'], 'walkout': base['walk'],
            **{k: base['counter'] * v / total for k, v in counts.items()}}


def projected_reply(th, before, terms, row):
    """Transfer a recorded response fraction and actual lever choices, not an old quote."""
    b = closing_terms(th.beliefs.case, before, th.std)
    ask = closing_terms(th.beliefs.case, terms, th.std)
    old, offered, reply = row['before'], row['offered'], row['returned']
    gap = old['unit_price'] - offered['unit_price']
    if abs(gap) < 0.01:
        # No identified numerical response slope to transfer to a different price request.
        if abs(b['unit_price'] - ask['unit_price']) > 0.01:
            return None
        price = b['unit_price'] * reply['unit_price'] / old['unit_price']
    else:
        if (b['unit_price'] - ask['unit_price']) * gap < 0:
            return None
        fraction = (old['unit_price'] - reply['unit_price']) / gap
