    neighbors = comparable(th, x)
    probabilities = reply_probabilities(th, terms, before, status, repeats, neighbors)
    branch = {'accepted_proposal': paired_gain(th, before, terms),
              'unchanged_offer': {'mean': 0.0, 'low': 0.0, 'high': 0.0},
              'walkout': {'mean': -secured, 'low': -secured, 'high': -secured}}
    scenarios = []
    for weight, row in neighbors:
        if row['economic_label'] not in ('improved_counteroffer', 'worse_offer') or not row['returned']:
            continue
        reply = projected_reply(th, before, terms, row)
        if reply is None or not valid(reply):
            continue
        gain = paired_gain(th, before, reply)
        kind = 'improved_counteroffer' if gain['mean'] > 0.01 else 'worse_offer' if gain['mean'] < -0.01 else 'unchanged_offer'
        if kind == 'unchanged_offer':
            continue
        scenarios.append({'weight': weight, 'kind': kind, 'terms': reply, 'gain': gain,
                          'event_id': row['event_id'], 'session_id': row['session_id']})
    # These are explicit ignorance scenarios when data cannot support a branch.
    # A deterioration can lose all currently secured reward. Do not assume the old quote survives.
    target = max(0.0, branch['accepted_proposal']['mean'])
    for kind in ('improved_counteroffer', 'worse_offer'):
        rows = [s for s in scenarios if s['kind'] == kind]
        if rows:
            total = sum(s['weight'] for s in rows)
            branch[kind] = {'mean': sum(s['weight'] * s['gain']['mean'] for s in rows) / total,
                            'low': min(s['gain']['low'] for s in rows),
                            'high': max(s['gain']['high'] for s in rows), 'source': 'projected comparable replies'}
        else:
            low, high = (0.0, target) if kind == 'improved_counteroffer' else (-secured, 0.0)
            branch[kind] = {'mean': (low + high) / 2, 'low': low, 'high': high,
                            'source': 'unobserved branch: explicit broad scenario, midpoint is an assumption'}
    # A rational terminal choice can decline a deteriorated deal; no deal is zero Arena reward.
    # It cannot recover the withdrawn old offer. The secured-reward floor is therefore -secured.
    for values in branch.values():
        for key in ('mean', 'low', 'high'):
            values[key] = max(-secured, values[key])
    estimate = {k: sum(probabilities[label] * branch[label][k] for label in OUTCOMES)
                for k in ('mean', 'low', 'high')}
    sessions = sorted({row['session_id'] for _, row in neighbors})
    evidence = {'observations': len(neighbors), 'independent_sessions': len(sessions),
                'session_ids': sessions, 'event_ids': [row['event_id'] for _, row in neighbors],
                'similarity_weight': sum(w for w, _ in neighbors),
                'unknown_branches': [k for k, v in branch.items() if v.get('source', '').startswith('unobserved')]}
    return {'pressure': x, 'probabilities': probabilities, 'branches': branch,
            'expected_extra_savings_eur': estimate, 'evidence': evidence,
            'assumptions': 'One supplier reply then close best feasible received deal or decline; old quote not guaranteed. '
                           'Probability estimates and scenario endpoints are not calibrated confidence bounds.',
            '_scenarios': scenarios, '_current_cost': current_cost}


def add_continuation_values(agent, board):
