                break
        for pid in shortlist:
            value = packages[pid]['continuation_value']
            followups = []
            # At most two counter scenarios, each from a different historical session.
            used = set()
            for scenario in sorted(value['_scenarios'], key=lambda s: s['weight'], reverse=True):
                if scenario['session_id'] in used:
                    continue
                used.add(scenario['session_id'])
                after = scenario['terms'];gain = scenario['gain']['mean']
                candidates = []
